(function() {
  fetch('/tmp/weekly_data.json').then(r => r.json()).then(data => {
    const ctx = document.getElementById('chartTimeSeries').getContext('2d');
    new Chart(ctx, {
      type: 'line',
      data: {
        labels: data.map(d => d.date),
        datasets: [
          {
            label: 'Petrol (avg)',
            data: data.map(d => d.petrol_avg),
            borderColor: colors.petrol,
            backgroundColor: 'rgba(88,166,255,0.1)',
            borderWidth: 2,
            pointRadius: 0,
            tension: 0.2,
          },
          {
            label: 'Diesel (avg)',
            data: data.map(d => d.diesel_avg),
            borderColor: colors.diesel,
            borderWidth: 2,
            pointRadius: 0,
            tension: 0.2,
          },
          {
            label: 'LPG (avg)',
            data: data.map(d => d.lpg_avg),
            borderColor: colors.lpg,
            borderWidth: 2,
            pointRadius: 0,
            tension: 0.2,
          },
          {
            label: 'Brent Crude ($/159L equivalent)',
            data: data.map(d => d.brent / 159),
            borderColor: colors.brent,
            borderDash: [6, 3],
            borderWidth: 1.5,
            pointRadius: 0,
            tension: 0.2,
          }
